56914,0.627648],[42.356946,0.627815],[42.357003,0.628045],[42.357065,0.628285],[42.357168,0.628639],[42.357263,0.628903],[42.357325,0.629069],[42.357401,0.629203],[42.357484,0.629315],[42.357644,0.629518],[42.357738,0.629616],[42.357837,0.629694],[42.357936,0.629777],[42.358016,0.629869],[42.358068,0.629933],[42.358166,0.630086],[42.358253,0.630215],[42.358293,0.630301],[42.358335,0.630428],[42.358387,0.630616],[42.358474,0.630959],[42.358541,0.631154],[42.358596,0.631305],[42.358677,0.631506],[42.358769,0.631704],[42.358903,0.631943],[42.359007,0.632108],[42.359118,0.632285],[42.359208,0.632388],[42.359329,0.632508],[42.35954,0.632685],[42.359666,0.632802],[42.359738,0.632885],[42.359804,0.63297],[42.359855,0.633076],[42.359912,0.633226],[42.360001,0.633468],[42.36007,0.633606],[42.360196,0.633882],[42.360286,0.634057],[42.360395,0.634211],[42.360516,0.634398],[42.360652,0.63456],[42.360705,0.634645],[42.36075,0.634754],[42.360736,0.634848],[42.360665,0.63492],[42.360575,0.634987],[42.360479,0.635069],[42.360428,0.635128],[42.36036,0.635247],[42.360296,0.635398],[42.360175,0.635681],[42.360116,0.635858],[42.360082,0.635979],[42.360017,0.636164],[42.359961,0.636283],[42.359895,0.636415],[42.359807,0.636529],[42.359665,0.636729],[42.359493,0.636975],[42.359444,0.637057],[42.359321,0.637289],[42.359266,0.637419],[42.359195,0.637612],[42.359162,0.637746],[42.359143,0.637916],[42.359136,0.638267],[42.359148,0.638439],[42.359174,0.638573],[42.359267,0.638952],[42.359385,0.639334],[42.359459,0.639574],[42.359511,0.63972],[42.359569,0.639921],[42.359631,0.640063],[42.35978,0.640347],[42.35992,0.640607],[42.359977,0.640714],[42.360001,0.640835]]$coords$::jsonb;
  v_landmarks jsonb := $landmarks$[[42.350457,0.620507],[42.367919,0.59304],[42.368097,0.59303],[42.369981,0.592217]]$landmarks$::jsonb;
  v_route record;
  v_points jsonb;
  v_count integer;
  v_length_km double precision;
  v_max_gap_km double precision;
  v_center_gap_km double precision;
  v_invalid integer;
  v_start_gap_m double precision;
  v_end_gap_m double precision;
  v_closing_gap_m double precision;
  v_landmark_gap_m double precision;
begin
  select jsonb_agg(jsonb_build_object(
    'lat',(point->>0)::double precision,
    'lon',(point->>1)::double precision
  ) order by ordinality)
    into v_points
    from jsonb_array_elements(v_coords)
      with ordinality as p(point,ordinality);
  select h.id,h.latitude,h.longitude,h.published,h.trace_available,
      h.official_url,h.description,h.distance_km,h.route_type,
      h.duration_minutes,h.ascent_m,
      t.status,t.segments,t.geometry_source,t.geometry_source_url,
      t.official,t.continuity_checked,t.checked_at
    into v_route
    from public.hiking_routes h
    join public.hiking_route_tracks t on t.route_id=h.id
    where h.id='osm-relation-9712657'
      and h.source='openstreetmap' and h.source_type='relation'
      and h.external_id=9712657
      and h.name='PR-HU 47'
      and h.route_ref='PR-HU 47' and h.raw_tags->>'ref'='PR-HU 47'
      and h.source_url='https://www.openstreetmap.org/relation/9712657'
      and (h.official_url is not distinct from null
        or h.official_url='https://turismoribagorza.org/ruta/pr-hu-47-beranuy-puyalto/')
      and h.region_code='huesca' and h.province='Huesca'
      and h.latitude=42.360128 and h.longitude=0.6165085
      and exists (select 1 from public.hiking_route_regions r
        where r.route_id=h.id and r.region_code='huesca' and r.published)
    for update of h,t;
  if not found then
    raise exception 'PR-HU 47 route identity or published region changed';
  end if;
  if v_route.status='ready' then
    if v_route.geometry_source_url='https://turismoribagorza.org/wp-content/uploads/2025/06/21_pr_hu_47.gpx'
      and v_route.geometry_source='Comarca de Ribagorza - GPX oficial PR-HU 47'
      and v_route.segments=jsonb_build_array(v_points)
      and v_route.official and v_route.continuity_checked
      and v_route.checked_at is not null
      and v_route.published and v_route.trace_available
      and v_route.official_url='https://turismoribagorza.org/ruta/pr-hu-47-beranuy-puyalto/'
      and v_route.distance_km=10.84
      and v_route.route_type='Lineal'
      and v_route.duration_minutes is null
      and v_route.ascent_m is null
      and v_route.description='PR-HU 47 desde Beranuy por el Camí del Grau, con visita al mirador del Mallo, las bordas de Beranuy y la ermita de Sis, hasta el enlace con el GR 18 junto al tozal de Puyalto. El GPX oficial contiene el recorrido de ida: 10,84 km. La ficha incluye el regreso a Beranuy.' then
      return;
    end if;
    raise exception 'PR-HU 47 route has another ready trace or publication state';
  end if;
  if v_route.status is distinct from 'missing'
    or v_route.published is distinct from false
    or v_route.trace_available is distinct from false
    or v_route.segments is not null or v_route.geometry_source_url is not null
    or v_route.geometry_source is distinct from 'OpenStreetMap'
    or v_route.official is distinct from false
    or v_route.continuity_checked is distinct from true
    or v_route.official_url is distinct from null
    or v_route.description is distinct from 'Beranuy (enlace con el GR18.1) - pico Puyalto (enlace con el GR-18)'
    or v_route.distance_km is distinct from 6
    or v_route.ascent_m is not null or v_route.duration_minutes is not null
    or v_route.route_type is distinct from null then
    raise exception 'PR-HU 47 hidden route state changed';
  end if;
  with points as (
    select ordinality idx,(point->>0)::double precision lat,
      (point->>1)::double precision lon
    from jsonb_array_elements(v_coords) with ordinality as p(point,ordinality)
  ), steps as (
    select *,lag(lat) over(order by idx) prev_lat,
      lag(lon) over(order by idx) prev_lon from points
  ), distances as (
    select case when prev_lat is null then 0 else
      ST_DistanceSphere(ST_MakePoint(lon,lat),
        ST_MakePoint(prev_lon,prev_lat))/1000 end step_km,
      ST_DistanceSphere(ST_MakePoint(lon,lat),
        ST_MakePoint(v_route.longitude,v_route.latitude))/1000 center_km,
      (lat between 42.35 and 42.37 and lon between 0.59 and 0.65) valid
    from steps
  )
  select count(*),coalesce(sum(step_km),0),coalesce(max(step_km),0),
    coalesce(min(center_km),999),count(*) filter(where not valid)
    into v_count,v_length_km,v_max_gap_km,v_center_gap_km,v_invalid
    from distances;
  select ST_DistanceSphere(
    ST_MakePoint((v_coords->0->>1)::double precision,(v_coords->0->>0)::double precision),
    ST_MakePoint(0.592217,42.36998)),
    ST_DistanceSphere(
    ST_MakePoint((v_coords->(v_count-1)->>1)::double precision,
      (v_coords->(v_count-1)->>0)::double precision),
    ST_MakePoint(0.640835,42.360001)),
    ST_DistanceSphere(
    ST_MakePoint((v_coords->0->>1)::double precision,(v_coords->0->>0)::double precision),
    ST_MakePoint((v_coords->(v_count-1)->>1)::double precision,
      (v_coords->(v_count-1)->>0)::double precision))
    into v_start_gap_m,v_end_gap_m,v_closing_gap_m;
  select max(nearest.gap_m) into v_landmark_gap_m
    from jsonb_array_elements(v_landmarks) as w(landmark)
    cross join lateral (
      select min(ST_DistanceSphere(
        ST_MakePoint((point->>1)::double precision,(point->>0)::double precision),
        ST_MakePoint((w.landmark->>1)::double precision,(w.landmark->>0)::double precision))) gap_m
      from jsonb_array_elements(v_coords) as p(point)
    ) nearest;
  if v_count<>753 or v_invalid>0
    or abs(v_length_km-10.836628)>0.015
    or v_max_gap_km>0.056 or v_center_gap_km>0.12
    or v_start_gap_m>2 or v_end_gap_m>2 or v_closing_gap_m<500
    or v_landmark_gap_m>10 then
    raise exception 'PR-HU 47 GPS validation failed: points %, length %, gap %, center %, start %, end %, closure %, landmarks %, invalid %',
      v_count,v_length_km,v_max_gap_km,v_center_gap_km,
      v_start_gap_m,v_end_gap_m,v_closing_gap_m,v_landmark_gap_m,v_invalid;
  end if;
  update public.hiking_route_tracks
    set status='ready',segments=jsonb_build_array(v_points),checked_at=now(),
      continuity_checked=true,geometry_source='Comarca de Ribagorza - GPX oficial PR-HU 47',
      geometry_source_url='https://turismoribagorza.org/wp-content/uploads/2025/06/21_pr_hu_47.gpx',official=true
    where route_id=v_route.id and status='missing';
  if not found then
    raise exception 'PR-HU 47 track state changed';
  end if;
  update public.hiking_routes
    set trace_available=true,published=true,
      distance_km=round(v_length_km::numeric,2),route_type='Lineal',
      official_url='https://turismoribagorza.org/ruta/pr-hu-47-beranuy-puyalto/',description='PR-HU 47 desde Beranuy por el Camí del Grau, con visita al mirador del Mallo, las bordas de Beranuy y la ermita de Sis, hasta el enlace con el GR 18 junto al tozal de Puyalto. El GPX oficial contiene el recorrido de ida: 10,84 km. La ficha incluye el regreso a Beranuy.'
    where id=v_route.id and not published and not trace_available;
  if not found then
    raise exception 'PR-HU 47 publication state changed';
  end if;
end
$curate$;
